SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(6*10^9);Alarm(500);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261031b/C48/inputs/two_isogeny_48_to_2_24.m";root:="work/deg10/continuation_20261031b/C48/";src:=eval Read(root cat "low_sources.m");k:=GF(5);R:=PolynomialRing(k);fields:=AssociativeArray();for r in src[1]do fields[r[1]]:=ext<k|R!r[2]>;end for;
function Key(v,d)ks:=[];for i in[1..d]do Append(~ks,&cat[[Integers()!a:a in Eltseq(z,k)]:z in v]);v:=[z^5:z in v];end for;return Sort(ks)[1];end function;
function CurveFrom(ky,d)K:=fields[d];b:=Evaluate(R!ky[1..d],K.1);c:=Evaluate(R!ky[d+1..2*d],K.1);E:=EllipticCurve([K|1-c,-b,-b,0,0]);return E,E![0,0];end function;
repidx:=AssociativeArray();for rr in src[3]do repidx[[rr[2]]cat rr[3]]:=rr[1];end for;records:=[* *];targets:=[* *];cache:=AssociativeArray();
for d in[3..8]do keys:={};for rr in src[3]do if rr[2]ne d then continue;end if;if d eq 8 then Include(~keys,rr[3]);else E,P:=CurveFrom(rr[3],d);for u in[1..24]do if GCD(u,48)eq 1 then Include(~keys,Key(TateNormalForm_bc(E,u*P),d));end if;end for;end if;end for;if d le 7 then assert #keys eq src[2][d];end if;
 for ky in Sort(Setseq(keys))do E,P:=CurveFrom(ky,d);EE,ls:=C48TwoIsogenousModuli(E,P);pairs:=[];ks:=[];for eps,eta in[0,1],u in[1,5,7,11]do bc:=DerickxNormalForm_bc(EE,ls`P+eps*(12*ls`Q),u*ls`Q+eta*ls`P);Append(~pairs,bc);Append(~ks,Key(bc,d));end for;can:=Sort(ks)[1];h:=Index(ks,can);e:=LCM([Degree(MinimalPolynomial(z,k)):z in pairs[1]]);assert d mod e eq 0 and d div e in[1,2];ck:=[d,e,d div e]cat can;if IsDefined(cache,ck)then ix:=cache[ck];else Append(~targets,[*d,can,e,d div e*]);ix:=#targets;cache[ck]:=ix;end if;sk:=[d]cat ky;ri:=IsDefined(repidx,sk)select repidx[sk]else 0;Append(~records,[*#records+1,d,ky,ri,ix,h*]);end for;
 print "D31B_C48_LOW_GEOMETRY_DEGREE",d,#keys,#records,#targets,Cputime(tt);
end for;Write(root cat "low_geometry.m",Sprint([*src[1],records,targets*]):Overwrite:=true);Write(root cat "low_character_targets.m",Sprint([*src[1],targets*]):Overwrite:=true);print "D31B_C48_LOW_GEOMETRY_COMPLETE",#records,#targets,Cputime(tt);quit;
